def evaluate(index: int, signal: float, stress: float,
             uncertainty: float) -> dict[str, float | bool]:
    """Dispatch only to one of this family's predefined functions."""
    if not 0 <= index < POLICY_COUNT:
        raise ValueError("Unknown policy index")
    function = globals()[f"dispatch_policy_{index:04d}"]
    return function(signal, stress, uncertainty)
